def present_titles(status, payload):
    if status != 200: return {"error": "Service unavailable"}
    if not isinstance(payload, dict) or not isinstance(payload.get("results"), list): return {"error": "Missing results"}
    if not all(isinstance(x, dict) and isinstance(x.get("title"), str) for x in payload["results"]): return {"error": "Invalid result"}
    return [x["title"] for x in payload["results"]]
